import{_ as l,o as i,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Performance Meeting 2023-08-17","description":"","frontmatter":{"title":"Ceph Performance Meeting 2023-08-17","date":"2023-08-17T00:00:00.000Z","updated":"2023-08-18T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","Erasure Coding","BlueFS"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Performance_Meeting_2023-08-17.md","filePath":"posts/2023/Ceph_Performance_Meeting_2023-08-17.md","lastUpdated":1780459816000}'),o={name:"posts/2023/Ceph_Performance_Meeting_2023-08-17.md"};function n(s,e,a,p,_,u){return i(),t("div",null,[...e[0]||(e[0]=[r("<p>本次Ceph性能会议主要讨论了以下议题：</p><ol><li><p><strong>PR审查与更新</strong>：</p><ul><li>讨论了两个更新的Pull Request，包括提升新写入对象读取性能的PR和优化BlueFS缓冲I/O使用的PR。</li><li>需要对Igor提交的PR进行详细审查，特别是评估其对BlueFS预取机制的影响。</li></ul></li><li><p><strong>Erasure Coding改进</strong>：</p><ul><li>正在进行的PR旨在改进Erasure Coding，计划重新审视数据缓存策略，特别是远程分片的缓存，以避免网络重传。</li></ul></li><li><p><strong>测试与性能优化</strong>：</p><ul><li>Gabby分享了关于大量对象创建、快照及克隆的测试结果，显示整体性能提升，特别是减少了在RocksDB中的多次访问。</li><li>讨论了可能的自动压缩机制，以及如何通过调整压缩设置来优化性能。</li></ul></li><li><p><strong>决定事项</strong>：</p><ul><li>对Igor的PR进行详细审查，评估其对BlueFS预取机制的影响。</li><li>继续关注和优化Erasure Coding的性能，特别是数据缓存策略。</li><li>对Gabby的测试结果进行深入分析，探索进一步的性能优化措施。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li>分配人员对未审查的PR进行详细评估。</li><li>继续关注和优化Erasure Coding的性能，特别是数据缓存策略。</li><li>对Gabby的测试结果进行深入分析，探索进一步的性能优化措施。</li></ul></li><li><p><strong>其他讨论</strong>：</p><ul><li>讨论了系统在处理大量数据时的CPU使用率问题，以及如何通过优化减少系统负载。</li><li>讨论了实际应用场景中可能遇到的问题，如心跳超时和系统资源占用问题。</li></ul></li></ol><p>会议中涉及的技术细节和具体代码改动需要通过代码审查和进一步测试来确认其效果和可行性。</p>",3)])])}const c=l(o,[["render",n]]);export{d as __pageData,c as default};
